  /*
   {"diagramJson": "{\"title\":\"Film scouting \\u00b7 1. Look: landscape and weather\",\"description\":\"Import and run once, in the Workflows app. For each area in reach: terrain, monthly climate and sunshine (CARTO Spatial Features), land cover (USDA/NLCD raster), hotel/tourism and healthcare POIs, county and state film incentives. Saves film_scout_cells (H3 res 6, for the map), film_scout_scoring (H3 res 4, for the agent tools) and film_scout_months (one row per area per month).\",\"nodes\":[{\"id\":\"s2\",\"data\":{\"id\":\"carto-do-public-data.carto.derived_spatialfeatures_usa_h3res8_v1_yearly_v4\",\"name\":\"ReadTable\",\"type\":\"table\",\"label\":\"derived_spatialfeatures_usa_h3res8_v1_yearly_v4\",\"inputs\":[{\"name\":\"source\",\"type\":\"String\",\"title\":\"Source table\",\"value\":\"carto-do-public-data.carto.derived_spatialfeatures_usa_h3res8_v1_yearly_v4\",\"description\":\"Read Table\"}]},\"type\":\"source\",\"position\":{\"x\":432,\"y\":0},\"selected\":false},{\"id\":\"n3\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"geoid, elevation, tmax_jan, tmax_feb, tmax_mar, tmax_apr, tmax_may, tmax_jun, tmax_jul, tmax_aug, tmax_sep, tmax_oct, tmax_nov, tmax_dec, tmin_jan, tmin_feb, tmin_mar, tmin_apr, tmin_may, tmin_jun, tmin_jul, tmin_aug, tmin_sep, tmin_oct, tmin_nov, tmin_dec, prec_jan, prec_feb, prec_mar, prec_apr, prec_may, prec_jun, prec_jul, prec_aug, prec_sep, prec_oct, prec_nov, prec_dec, srad_jan, srad_feb, srad_mar, srad_apr, srad_may, srad_jun, srad_jul, srad_aug, srad_sep, srad_oct, srad_nov, srad_dec, tourism, healthcare, food_drink, population, prec_jan + prec_feb + prec_mar + prec_apr + prec_may + prec_jun + prec_jul + prec_aug + prec_sep + prec_oct + prec_nov + prec_dec AS prec_year_mm, `carto-un`.carto.H3_TOPARENT(geoid, 4) AS area_id\",\"description\":\"SELECT statement\",\"placeholder\":\"E.g.: *, distance_in_km * 1000 AS distance_in_meters\",\"allowExpressions\":false}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":656,\"y\":0},\"selected\":false},{\"id\":\"n4\",\"data\":{\"name\":\"native.h3toparent\",\"type\":\"generic\",\"label\":\"H3 To Parent\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"h3\",\"type\":\"Column\",\"title\":\"H3 index column\",\"value\":\"geoid\",\"parent\":\"source\",\"dataType\":[\"string\"],\"description\":\"H3 index column\"},{\"max\":15,\"min\":0,\"mode\":\"slider\",\"name\":\"resolution\",\"type\":\"Number\",\"title\":\"Resolution\",\"value\":6,\"description\":\"Resolution\"}],\"version\":\"1.0.0\"},\"type\":\"generic\",\"position\":{\"x\":784,\"y\":0},\"selected\":false},{\"id\":\"n5\",\"data\":{\"name\":\"native.joinv2\",\"type\":\"generic\",\"label\":\"Join\",\"inputs\":[{\"name\":\"lefttable\",\"type\":\"Table\",\"title\":\"Left table\",\"description\":\"Left table\"},{\"name\":\"righttable\",\"type\":\"Table\",\"title\":\"Right table\",\"description\":\"Right table\"},{\"name\":\"lefttablekeycolumn\",\"type\":\"Column\",\"title\":\"Key column in left table\",\"value\":\"h3_parent\",\"parent\":\"lefttable\",\"dataType\":[\"boolean\",\"date\",\"datetime\",\"time\",\"timestamp\",\"number\",\"string\"],\"description\":\"Key column in left table\"},{\"name\":\"lefttablecolumns\",\"type\":\"ColumnsForJoin\",\"title\":\"Left table columns\",\"value\":\"[{\\\"name\\\": \\\"geoid\\\", \\\"joinname\\\": \\\"geoid\\\"}, {\\\"name\\\": \\\"elevation\\\", \\\"joinname\\\": \\\"elevation\\\"}, {\\\"name\\\": \\\"tmax_jan\\\", \\\"joinname\\\": \\\"tmax_jan\\\"}, {\\\"name\\\": \\\"tmax_feb\\\", \\\"joinname\\\": \\\"tmax_feb\\\"}, {\\\"name\\\": \\\"tmax_mar\\\", \\\"joinname\\\": \\\"tmax_mar\\\"}, {\\\"name\\\": \\\"tmax_apr\\\", \\\"joinn