false}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":3104,\"y\":0},\"selected\":false},{\"id\":\"f_n10\",\"data\":{\"name\":\"native.saveastable\",\"type\":\"generic\",\"label\":\"Save as Table\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"destination\",\"type\":\"OutputTable\",\"title\":\"Table details\",\"value\":\"YOUR_PROJECT.YOUR_DATASET.film_scout_landscape\",\"description\":\"Table details\",\"placeholder\":\"Rename and select destination\"},{\"name\":\"append\",\"type\":\"Boolean\",\"title\":\"Append to existing table\",\"value\":false,\"default\":false,\"description\":\"Append to existing table\"},{\"name\":\"optimizationcol\",\"type\":\"Column\",\"title\":\"Cluster by\",\"parent\":\"source\",\"advanced\":true,\"dataType\":[\"geography\",\"boolean\",\"number\",\"string\",\"date\",\"datetime\",\"time\",\"timestamp\"],\"optional\":true,\"providers\":[\"bigquery\"],\"description\":\"Cluster by\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":3392,\"y\":0},\"selected\":false},{\"id\":\"m_s\",\"data\":{\"id\":\"carto-do-public-data.usa_tiger.geography_usa_state_2024\",\"name\":\"ReadTable\",\"type\":\"table\",\"label\":\"geography_usa_state_2024\",\"inputs\":[{\"name\":\"source\",\"type\":\"String\",\"title\":\"Source table\",\"value\":\"carto-do-public-data.usa_tiger.geography_usa_state_2024\",\"description\":\"Read Table\"}]},\"type\":\"source\",\"position\":{\"x\":1072,\"y\":64},\"selected\":false},{\"id\":\"m_w\",\"data\":{\"name\":\"native.where\",\"type\":\"generic\",\"label\":\"Where\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Filter expression\",\"value\":\"STUSPS IN ('WA','OR','ID','MT','WY','CA','NV','UT','CO','AZ','NM')\",\"description\":\"Filter expression\",\"placeholder\":\"E.g.: area > 1000 AND area < 3000\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":1296,\"y\":64},\"selected\":false},{\"id\":\"m_p\",\"data\":{\"name\":\"native.h3polyfill\",\"type\":\"generic\",\"label\":\"H3 Polyfill\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"geo\",\"type\":\"Column\",\"title\":\"Geo column\",\"value\":\"geom\",\"parent\":\"source\",\"dataType\":[\"geography\"],\"description\":\"Geo column\"},{\"max\":15,\"min\":0,\"mode\":\"slider\",\"name\":\"resolution\",\"type\":\"Number\",\"title\":\"Resolution\",\"value\":6,\"helper\":\"Hexagon edge length: 2=182km | 6=4km | 10=76m | 14=1.5m\",\"default\":8,\"description\":\"Resolution\"},{\"name\":\"aggregate\",\"type\":\"Boolean\",\"title\":\"Aggregate H3 cells\",\"value\":true,\"helper\":\"If false, the result will include the original columns from the input source\",\"default\":false,\"description\":\"Aggregate H3 cells\"},{\"name\":\"includegeocolumns\",\"type\":\"Boolean\",\"title\":\"Include geo columns\",\"value\":false,\"helper\":\"If true, the result will include the original geo column(s)\",\"showIf\":[{\"value\":false,\"parameter\":\"aggregate\"}],\"default\":false,\"description\":\"Include geo columns\"},{\"mode\":\"toggle\",\"name\":\"mode\",\"type\":\"Selection\",\"title\":\"Mode\",\"value\":\"center\",\"default\":\"center\",\"options\":[\"center\",\"intersects\",\"contains\"],\"providers\":[\"postgres\",\"bigquery\"],\"description\":\"Mode\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":1440,\"y\":48},\"selected\":false},{\"id\":\"note_overview\",\"data\":{\"name\":\"Note\",\"color\":\"#E5E5E5\",\"genAi\":false,\"label\":\"\",\"width\":360,\"height\":820,\"inputs\":[],\"markdown\":\"---\\nlabel: Workflow 1 \\u00b7 Look\\n---\\n## 1 \\u00b7 Look: landscape and weather\\nDescribes every **scouting area** (H3 resolution 4, about 40 km across) in the 11 western states: terrain, land cover, monthly climate, and places nearby.\\n\\n**Run first**, in the Workflows app (about 3-4 min, mostly the land cover raster).\\n\\n**Output:** `film_scout_landscape`, read by workflow 2 \\u00b7 Logistics.\\n\\n**Sources:** CARTO Spatial Features (Data Observatory), USDA Cropland Data Layer raster, US Census TIGER states.\",\"position\":{\"x\":0,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":0,\"y\":-300},\"selected\":false},{\"id\":\"note_1\",\"data\":{\"name\":\"Note\",\"color\":\"#F6CF71\",\"genAi\":false,\"label\":\"\",\"width\":568,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 1. Climate, terrain and places\\n---\\n**CARTO Spatial Features**: one row per H3 res-8 cell (about 0.7 km\\u00b2) with elevation, monthly WorldClim climate (1970-2000), POI counts and population.\\n\\n- **Select** keeps the columns we need, adds annual precipitation and each cell's scouting area (`area_id`, res 4).\\n- **H3 To Parent** adds the res-6 cell (`h3_parent`) used to match the western grid.\",\"position\":{\"x\":408,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":408,\"y\":-300},\"selected\":false},{\"id\":\"note_2\",\"data\":{\"name\":\"Note\",\"color\":\"#9EB9F3\",\"genAi\":false,\"label\":\"\",\"width\":568,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 2. Western US as an H3 grid\\n---\\n- **US states** (TIGER 2024)\\n- **Where** keeps the 11 western states.\\n- **H3 Polyfill** turns them into res-6 cells.\",\"position\":{\"x\":1048,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":1048,\"y\":-300},\"selected\":false},{\"id\":\"note_3\",\"data\":{\"name\":\"Note\",\"color\":\"#87C55F\",\"genAi\":false,\"label\":\"\",\"width\":216,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 3. Keep cells in the West\\n---\\n**Join** (inner) on the res-6 cell: drops Spatial Features cells outside the 11 states.\",\"position\":{\"x\":1688,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":1688,\"y\":-300},\"selected\":false},{\"id\":\"note_4\",\"data\":{\"name\":\"Note\",\"color\":\"#FE88B1\",\"genAi\":false,\"label\":\"\",\"width\":568,\"height\":740,\"inputs\":[],\"markdown\":\"---\\nlabel: 4. Land cover from the USDA raster\\n---\\n- **Select** makes a point at each cell's center.\\n- **Get Values from Raster** reads the USDA Cropland Data Layer class at that point. *The slow step.*\\n- **Select** turns class codes into 0/1 flags: forest (141-143, 63), shrub (152, 64), grass (176), barren (131, 65), snow (112), water (111), developed (121-124), wetland (190, 195), crops.\",\"position\":{\"x\":1976,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":1976,\"y\":-300},\"selected\":false},{\"id\":\"note_5\",\"data\":{\"name\":\"Note\",\"color\":\"#C9DB74\",\"genAi\":false,\"label\":\"\",\"width\":216,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 5. Add land cover to each cell\\n---\\n**Join** (left) on the cell ID adds the land cover flags to the climate and terrain columns.\",\"position\":{\"x\":2616,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":2616,\"y\":-300},\"selected\":false},{\"id\":\"note_6\",\"data\":{\"name\":\"Note\",\"color\":\"#8BE0A4\",\"genAi\":false,\"label\":\"\",\"width\":392,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 6. Roll up to scouting areas\\n---\\n- **Group by** `area_id`: averages climate and land cover flags, min/max elevation, sums POIs and population, counts cells (`map_cells` = res-6 cells).\\n- **Select** converts units (m \\u2192 ft, \\u00b0C \\u2192 \\u00b0F, mm \\u2192 in, flags \\u2192 %) and gives plain names like `oct_high_f`, `pct_forest`.\",\"position\":{\"x\":2904,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":2904,\"y\":-300},\"selected\":false},{\"id\":\"note_7\",\"data\":{\"name\":\"Note\",\"color\":\"#B497E7\",\"genAi\":false,\"label\":\"\",\"width\":216,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 7. Save\\n---\\n**Save as Table** \\u2192 `film_scout_landscape` (one row per scouting area).\",\"position\":{\"x\":3368,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":3368,\"y\":-300},\"selected\":false}],\"edges\":[{\"id\":\"e1\",\"source\":\"s2\",\"target\":\"n3\",\"sourceHandle\":\"out\",\"targetHandle\":\"table\"},{\"id\":\"e2\",\"source\":\"n3\",\"target\":\"n4\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"},{\"id\":\"e3\",\"source\":\"n4\",\"target\":\"n5\",\"sourceHandle\":\"result\",\"targetHandle\":\"lefttable\"},{\"id\":\"e6\",\"source\":\"s7\",\"target\":\"n8\",\"sourceHandle\":\"out\",\"targetHandle\":\"source\"},{\"id\":\"e8\",\"source\":\"n8\",\"target\":\"n9\",\"sourceHandle\":\"result\",\"targetHandle\":\"table\"},{\"id\":\"e_join_points\",\"source\":\"n5\",\"target\":\"n_cell_points\",\"sourceHandle\":\"result\",\"targetHandle\":\"table\"},{\"id\":\"e_points_raster\",\"source\":\"n_cell_points\",\"target\":\"n8\",\"sourceHandle\":\"result\",\"targetHandle\":\"vector\"},{\"id\":\"e_join_back_left\",\"source\":\"n5\",\"target\":\"n_add_landcover\",\"sourceHandle\":\"result\",\"targetHandle\":\"lefttable\"},{\"id\":\"e_flags_back\",\"source\":\"n9\",\"target\":\"n_add_landcover\",\"sourceHandle\":\"result\",\"targetHandle\":\"righttable\"},{\"id\":\"2bab15f9-89b6-4204-aa98-f1a9f70db442\",\"type\":\"default\",\"source\":\"n_add_landcover\",\"target\":\"e2fa86a3-29c9-4cda-aa7e-6d510790e436\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"},{\"id\":\"m_e1\",\"source\":\"m_s\",\"target\":\"m_w\",\"sourceHandle\":\"out\",\"targetHandle\":\"source\"},{\"id\":\"m_e2\",\"source\":\"m_w\",\"target\":\"m_p\",\"sourceHandle\":\"match\",\"targetHandle\":\"source\"},{\"id\":\"m_e3\",\"source\":\"m_p\",\"target\":\"n5\",\"sourceHandle\":\"result\",\"targetHandle\":\"righttable\"},{\"id\":\"k_e1\",\"source\":\"e2fa86a3-29c9-4cda-aa7e-6d510790e436\",\"target\":\"f_n1\",\"sourceHandle\":\"result\",\"targetHandle\":\"table\"},{\"id\":\"k_e2\",\"source\":\"f_n1\",\"target\":\"f_n10\",\"sourceHan